const CACHE_NAME="roomvibe-cache-v1",baseURL="http://localhost/room-vibe-backend/frontend",urlsToCache=[`${baseURL}/images/`,"https://cdn.jsdelivr.net/npm/tailwindcss@2.2.19/dist/tailwind.min.css","https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.4/css/all.min.css","https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap","https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css","https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.4/webfonts/fa-brands-400.eot","https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.4/webfonts/fa-brands-400.svg","https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.4/webfonts/fa-brands-400.ttf","https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.4/webfonts/fa-brands-400.woff2","https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.4/webfonts/fa-solid-900.eot","https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.4/webfonts/fa-solid-900.svg","https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.4/webfonts/fa-solid-900.ttf","https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.4/webfonts/fa-solid-900.woff2"];self.addEventListener("install",(event=>{event.waitUntil(caches.open(CACHE_NAME).then((cache=>(console.log("Caching static resources..."),cache.addAll(urlsToCache)))))})),self.addEventListener("activate",(event=>{const cacheWhitelist=[CACHE_NAME];event.waitUntil(caches.keys().then((cacheNames=>Promise.all(cacheNames.map((cacheName=>{if(!cacheWhitelist.includes(cacheName))return caches.delete(cacheName)}))))))})),self.addEventListener("fetch",(event=>{event.respondWith(caches.match(event.request).then((cachedResponse=>cachedResponse||fetch(event.request).then((networkResponse=>caches.open(CACHE_NAME).then((cache=>(cache.put(event.request,networkResponse.clone()),networkResponse))))))))}));